alter table settlement_account_mapper
add column transaction_type_code smallint;

alter table settlement_account_mapper
drop constraint settlement_account_mapper_transaction_source_code_key;

alter table settlement_account_mapper
add constraint settlement_account_mapper_source_type_code_key unique(transaction_source_code,
transaction_type_code);

update settlement_account_mapper set transaction_type_code = 3, description = 'purchase' where
transaction_type_code is null;

