CREATE TABLE IF NOT EXISTS internal_account_mapping
(
    id bigserial NOT NULL PRIMARY KEY,
    domain varchar(4) NOT NULL,
    family varchar(4) NOT NULL,
    sub_family varchar(4) NOT NULL,
    description varchar(50) NOT NULL,
    channel varchar(50) NOT NULL,
    account_number varchar(20) NOT NULL,
    client_id varchar(100) NOT NULL,
    aml_check boolean NOT NULL DEFAULT TRUE,
    created_at timestamp without time zone NULL DEFAULT now(),
    last_updated_at timestamp without time zone null default now()
);
